async function withFallback(call, fallbackFn) {
  try {
    return await call();
  } catch (err) {
    // dependency failed or breaker open — degrade
    return await fallbackFn();
  }
}

// usage:
const recs = await withFallback(
  () => recsService.get(userId),
  () => db.query('SELECT ... expensive aggregate ...')  // recompute live
);
